const threadTipGlow=new THREE.Mesh(new THREE.SphereGeometry(.041,10,8),new THREE.MeshBasicMaterial({color:0xffe9c4,transparent:true,opacity:.18,blending:THREE.AdditiveBlending,depthWrite:false}));
